window.MG_LAZY_DATA["data/lazy/owner-resources/b456-2915e6fe58a8a1e4.json"]={sha256:"2915e6fe58a8a1e413fe0badb807c0e10e831c6733095c6be72658a7a059c7b5",value:{"sources":[{"id":"b-src-environment","title":"Research on Innovative and Alternative Wastewater Technologies","url":"https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: wastewater technologies and treatment references. Not individual verification of every named environmental project."},{"id":"b-src-waste","title":"Sustainable Materials Management","url":"https://www.epa.gov/smm","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: materials life cycles, waste prevention, recycling and recovery."},{"id":"b-src-wastewater","title":"Wastewater Technology Fact Sheets","url":"https://www.epa.gov/septic/wastewater-technology-fact-sheets","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: disinfection, constructed wetlands, package plants, sewer technologies and treatment."},{"id":"v17s-urban-green","title":"綠色基礎設施類型","titleEn":"Types of Green Infrastructure","url":"https://www.epa.gov/green-infrastructure/types-green-infrastructure","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-swmm","title":"暴雨逕流與低衝擊開發模型","titleEn":"Storm Water Management Model (SWMM)","url":"https://www.epa.gov/water-research/storm-water-management-model-swmm","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"media":{"courses":[{"courseId":"b456","videos":[],"guides":[{"id":"b456-v17-practice","title":"工程操作與定量驗證手冊","titleEn":"Engineering actions and quantitative verification","concept":"以「綠屋頂的水、重量與防水界面」為主線，依序完成十個專題單元。學徒在場景中辨識設備、列出邊界、重算明示的教學算例、比較量測與模型，最後診斷故障並交付證據。每一單元保留機制、算例、驗證與失效四種學習任務。","conceptEn":"Follow water, weight and waterproofing interfaces in green roofs through ten technical units. Identify equipment in the scene, define boundaries, reproduce explicitly hypothetical examples, compare measurements with models, and diagnose faults before handing over evidence. Each unit contains mechanism, calculation, verification and failure tasks.","procedure":["在「屋面集水邊界」的教學模型或試算表中先重現 5 m3，再依驗證任務改動一個輸入、保留其餘條件。對照「排水分區錯置會低估個別排水口流量。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「飽和載重」的教學模型或試算表中先重現 144 kg/m2，再依驗證任務改動一個輸入、保留其餘條件。對照「以乾密度檢核結構會漏掉蓄水重量。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「可用蓄水量」的教學模型或試算表中先重現 3.6 m3，再依驗證任務改動一個輸入、保留其餘條件。對照「連續降雨時沿用乾屋頂容量會高估滯洪。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「排水與溢流分流」的教學模型或試算表中先重現 1.5 L/s，再依驗證任務改動一個輸入、保留其餘條件。對照「主排水堵塞而溢流同樣受阻會造成積水增重。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「防水搭接與穿孔」的教學模型或試算表中先重現 784.8 Pa，再依驗證任務改動一個輸入、保留其餘條件。對照「看不到室內滴水不代表防水層沒有局部受損。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「過濾層與介質流失」的教學模型或試算表中先重現 0.1 kg，再依驗證任務改動一個輸入、保留其餘條件。對照「濾層堵塞會造成上方積水，破損則使介質流失。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「蒸散恢復容量」的教學模型或試算表中先重現 1.2 m3，再依驗證任務改動一個輸入、保留其餘條件。對照「將潛在蒸散當實際值會高估乾燥恢復。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「土壤濕度感測」的教學模型或試算表中先重現 30 mm，再依驗證任務改動一個輸入、保留其餘條件。對照「使用礦質土校正於輕質介質可能有系統偏差。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「降雨削峰與時間步長」的教學模型或試算表中先重現 0.4 fraction，再依驗證任務改動一個輸入、保留其餘條件。對照「低頻平均值可能把真正的排水尖峰抹平。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「檢修台帳與季節巡查」的教學模型或試算表中先重現 0.916667 fraction，再依驗證任務改動一個輸入、保留其餘條件。對照「以外觀綠意判定排水良好會漏掉隱蔽堵塞。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。"],"procedureEn":["In the teaching model or spreadsheet for roof catchment boundary, first reproduce 5 m3, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Incorrect drainage zoning understates individual outlet flows.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for saturated loading, first reproduce 144 kg/m2, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Checking with dry density omits stored-water mass.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for available storage, first reproduce 3.6 m3, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Using dry-roof capacity during repeated storms overstates retention.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for drainage and overflow routing, first reproduce 1.5 L/s, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Blocking both primary drain and overflow adds ponded load.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for waterproofing joints and penetrations, first reproduce 784.8 Pa, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"No indoor dripping does not prove the membrane is intact.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for filter layer and media loss, first reproduce 0.1 kg, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"A clogged filter ponds water; a torn filter loses media.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for evapotranspiration restores capacity, first reproduce 1.2 m3, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Using potential as actual evapotranspiration overstates recovery.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for substrate moisture sensing, first reproduce 30 mm, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Using mineral-soil calibration for lightweight substrate introduces bias.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for peak attenuation and time step, first reproduce 0.4 fraction, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Low-frequency averaging can erase actual drainage peaks.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for inspection ledger and seasonal checks, first reproduce 0.916667 fraction, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Green appearance can conceal blocked drains.\" and submit baseline and changed values, units, and one measurement that distinguishes them."],"evidence":["沿屋面坡向標示200m2的集水邊界。","列出各層飽和質量，與結構設計資料對照。","把初始含水率提高，重算剩餘容量。","封閉一個教學排水口，觀察水位與溢流路徑。","在模型標記穿孔並比較不同水深的壓力。","採集排水測懸浮固體，對照介質表面沉陷。","比較一天與三天乾燥間隔的下場雨容量。","用秤重法與感測值在三種含水率下比較。","以1分鐘及15分鐘資料比較峰值遺失程度。","把未檢查的排水口列成待辦並保留位置照片。"],"evidenceEn":["Map the200m2 catchment along roof slopes.","List saturated layer masses and compare with structural design data.","Raise initial moisture and recalculate remaining storage.","Close one simulated outlet and observe ponding and overflow.","Mark penetrations in the model and compare pressures at different depths.","Measure solids in drainage and compare surface settlement.","Compare next-storm capacity after one versus three dry days.","Compare gravimetric and sensor estimates at three moisture levels.","Compare peak loss using one- and15-minute data.","Track unchecked outlets as tasks with location photos."],"pitfalls":["排水分區錯置會低估個別排水口流量。","以乾密度檢核結構會漏掉蓄水重量。","連續降雨時沿用乾屋頂容量會高估滯洪。","主排水堵塞而溢流同樣受阻會造成積水增重。","看不到室內滴水不代表防水層沒有局部受損。","濾層堵塞會造成上方積水，破損則使介質流失。","將潛在蒸散當實際值會高估乾燥恢復。","使用礦質土校正於輕質介質可能有系統偏差。","低頻平均值可能把真正的排水尖峰抹平。","以外觀綠意判定排水良好會漏掉隱蔽堵塞。"],"pitfallsEn":["Incorrect drainage zoning understates individual outlet flows.","Checking with dry density omits stored-water mass.","Using dry-roof capacity during repeated storms overstates retention.","Blocking both primary drain and overflow adds ponded load.","No indoor dripping does not prove the membrane is intact.","A clogged filter ponds water; a torn filter loses media.","Using potential as actual evapotranspiration overstates recovery.","Using mineral-soil calibration for lightweight substrate introduces bias.","Low-frequency averaging can erase actual drainage peaks.","Green appearance can conceal blocked drains."],"sourceIds":["v17s-urban-green","v17s-urban-swmm"],"sources":[{"id":"v17s-urban-green","title":"綠色基礎設施類型","titleEn":"Types of Green Infrastructure","url":"https://www.epa.gov/green-infrastructure/types-green-infrastructure","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-swmm","title":"暴雨逕流與低衝擊開發模型","titleEn":"Storm Water Management Model (SWMM)","url":"https://www.epa.gov/water-research/storm-water-management-model-swmm","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"simulationOnly":true,"scope":"公開原理與資料支持的原創教學。算例中的輸入為明示教學假設，非該設施實測或操作設定。此處任務在離線模型完成，不能作為現場設計、飲用水合格或設備操作許可。","scopeEn":"Original teaching based on public principles and sources. Numerical inputs are explicit teaching assumptions, not site measurements or operating setpoints. Tasks use offline models and do not certify field design, potable-water compliance or equipment operation."}]}]},"related":{"courses":[{"courseId":"b456","overview":"跨單元連結與比較練習","overviewEn":"Cross-process connections and comparisons","related":[{"id":"b415","title":"首爾清溪川復育","titleEn":"Seoul Cheonggyecheon restoration","why":"比較兩個系統的物質或能量收支，列出不可直接沿用的邊界條件。","whyEn":"Compare material or energy balances and identify boundary conditions that cannot be transferred.","transfer":"守恆、量測與失效驗證","transferEn":"Conservation, measurement and failure verification","difference":"設備尺度、進料組成與品質目標必須分別設定。","differenceEn":"Equipment scale, feed composition and quality objectives require separate definitions.","practice":["各選一個教學算例，記下輸入、輸出與單位。","對照兩課的系統邊界，說明哪些假設不能沿用。","改變一個輸入，提出量測與失效判據來核對結果。"],"practiceEn":["Choose one worked example from each course and record inputs, outputs and units.","Compare system boundaries and identify assumptions that cannot transfer.","Change one input and propose measurements and failure criteria to check the result."],"place":{"name":"首爾代表點","nameEn":"Seoul reference point","country":"南韓","countryEn":"South Korea","lat":37.57,"lon":126.98,"coordinateScope":"approximate-city-reference; not a facility entrance","lng":126.98,"coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"referenceUrls":["https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","https://www.epa.gov/smm","https://www.epa.gov/septic/wastewater-technology-fact-sheets"]},{"id":"b416","title":"新加坡碧山—宏茂橋公園河川復育","titleEn":"Bishan–Ang Mo Kio Park river restoration","why":"比較兩個系統的物質或能量收支，列出不可直接沿用的邊界條件。","whyEn":"Compare material or energy balances and identify boundary conditions that cannot be transferred.","transfer":"守恆、量測與失效驗證","transferEn":"Conservation, measurement and failure verification","difference":"設備尺度、進料組成與品質目標必須分別設定。","differenceEn":"Equipment scale, feed composition and quality objectives require separate definitions.","practice":["各選一個教學算例，記下輸入、輸出與單位。","對照兩課的系統邊界，說明哪些假設不能沿用。","改變一個輸入，提出量測與失效判據來核對結果。"],"practiceEn":["Choose one worked example from each course and record inputs, outputs and units.","Compare system boundaries and identify assumptions that cannot transfer.","Change one input and propose measurements and failure criteria to check the result."],"place":{"name":"新加坡","nameEn":"Singapore","country":"新加坡","countryEn":"Singapore","lat":1.35,"lon":103.82,"coordinateScope":"approximate-city-reference; not a facility entrance","lng":103.82,"coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"referenceUrls":["https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","https://www.epa.gov/smm","https://www.epa.gov/septic/wastewater-technology-fact-sheets"]}],"references":[{"id":"b-src-environment","title":"Research on Innovative and Alternative Wastewater Technologies","url":"https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: wastewater technologies and treatment references. Not individual verification of every named environmental project."},{"id":"b-src-waste","title":"Sustainable Materials Management","url":"https://www.epa.gov/smm","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: materials life cycles, waste prevention, recycling and recovery."},{"id":"b-src-wastewater","title":"Wastewater Technology Fact Sheets","url":"https://www.epa.gov/septic/wastewater-technology-fact-sheets","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: disinfection, constructed wetlands, package plants, sewer technologies and treatment."},{"id":"v17s-urban-green","title":"綠色基礎設施類型","titleEn":"Types of Green Infrastructure","url":"https://www.epa.gov/green-infrastructure/types-green-infrastructure","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-swmm","title":"暴雨逕流與低衝擊開發模型","titleEn":"Storm Water Management Model (SWMM)","url":"https://www.epa.gov/water-research/storm-water-management-model-swmm","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}]}]},"places":{"courses":[{"courseId":"b456","place":{"name":"美國EPA總部：方法資料來源機構（非實廠）","nameEn":"US EPA headquarters: methodology source institution (not a process plant)","country":"美國","countryEn":"United States","lat":38.8941,"lon":-77.0298,"coordinateScope":"近似機構所在區域位置；依公開地址作教材地圖代表點，非建物入口、實廠、實測或導航位置。","coordinateScopeEn":"Approximate institution-area location inferred from its public address for the teaching map; not a building entrance, process plant, surveyed point or navigation coordinate.","locationSourceUrl":"https://www.epa.gov/aboutepa/visiting-epa-headquarters","locationVerified":"2026-10-23","lng":-77.0298},"summary":"本課以來源所列的技術指引與研究為閱讀脈絡，並非重建某一設施的工程沿革；算例、數據與場景參數皆為原創教學假設。比較舊方法與感測、控制、資源回收整合的方法時，先固定處理功能及系統邊界，再評估效率與可靠度。","summaryEn":"The cited technical guidance and research provide a reading pathway, not the engineering history of a particular facility. Examples, data and scene parameters are original teaching assumptions. When comparing conventional methods with integrated sensing, control and resource recovery, hold the treatment function and system boundary fixed before assessing efficiency and reliability.","history":[{"year":"工程背景","title":"屋頂綠化排水與防水","titleEn":"Green-roof drainage and waterproofing","text":"本課以來源所列的技術指引與研究為閱讀脈絡，並非重建某一設施的工程沿革；算例、數據與場景參數皆為原創教學假設。比較舊方法與感測、控制、資源回收整合的方法時，先固定處理功能及系統邊界，再評估效率與可靠度。","textEn":"The cited technical guidance and research provide a reading pathway, not the engineering history of a particular facility. Examples, data and scene parameters are original teaching assumptions. When comparing conventional methods with integrated sensing, control and resource recovery, hold the treatment function and system boundary fixed before assessing efficiency and reliability."}],"connection":"以「綠屋頂的水、重量與防水界面」為主線，依序完成十個專題單元。學徒在場景中辨識設備、列出邊界、重算明示的教學算例、比較量測與模型，最後診斷故障並交付證據。每一單元保留機制、算例、驗證與失效四種學習任務。","connectionEn":"Follow water, weight and waterproofing interfaces in green roofs through ten technical units. Identify equipment in the scene, define boundaries, reproduce explicitly hypothetical examples, compare measurements with models, and diagnose faults before handing over evidence. Each unit contains mechanism, calculation, verification and failure tasks.","references":[{"id":"v17s-urban-green","title":"綠色基礎設施類型","titleEn":"Types of Green Infrastructure","url":"https://www.epa.gov/green-infrastructure/types-green-infrastructure","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-swmm","title":"暴雨逕流與低衝擊開發模型","titleEn":"Storm Water Management Model (SWMM)","url":"https://www.epa.gov/water-research/storm-water-management-model-swmm","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"sourceIds":["v17s-urban-green","v17s-urban-swmm"]}]},"vendors":{"courses":[],"vendors":[]}}};
